import{_ as o,c as i,o as a,ae as t}from"./chunks/framework.DEXG3EuZ.js";const g=JSON.parse('{"title":"Migrating from v1 to v2","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/migration-v2.md","filePath":"en/guide/migration-v2.md","lastUpdated":1792605191000}'),n={name:"en/guide/migration-v2.md"};function r(s,e,d,l,c,m){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="migrating-from-v1-to-v2" tabindex="-1">Migrating from v1 to v2 <a class="header-anchor" href="#migrating-from-v1-to-v2" aria-label="Permalink to &quot;Migrating from v1 to v2&quot;">​</a></h1><h2 id="breaking-changes" tabindex="-1">Breaking Changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking Changes&quot;">​</a></h2><ul><li>Minimum Node.js is now 22.12; builds use Vite 8 and Rolldown.</li><li>Login moved from <code>/api/login</code> to <code>/api/auth/login</code>.</li><li>Requests use <code>src/api/client.ts</code> plus <code>src/api/modules</code>; <code>utils/request</code> is a compatibility re-export only.</li><li><code>VITE_USE_PWA</code> became <code>VITE_PWA_ENABLED</code>.</li><li>Three simultaneous UI resolvers became one <code>VITE_UI_FRAMEWORK</code> selection.</li><li>Token persistence moved from <code>localStorage</code> to <code>sessionStorage</code>.</li><li>Main route names/navigation became Home / Examples / AI / Member.</li></ul><h2 id="migration-steps" tabindex="-1">Migration Steps <a class="header-anchor" href="#migration-steps" aria-label="Permalink to &quot;Migration Steps&quot;">​</a></h2><ol><li>Upgrade Node/pnpm and run <code>pnpm install</code>.</li><li>Migrate environment values from <code>.env.example</code> and select a UI framework.</li><li>Move direct Axios calls into <code>src/api/modules</code> and adopt <code>ApiError</code>.</li><li>Move remote lists/details from Pinia to TanStack Query.</li><li>Replace <code>openapi/schema.yaml</code> and run <code>pnpm api:generate</code>.</li><li>Move product SVGs to <code>src/assets/icons</code> and extend <code>SvgIconName</code>.</li><li>Review custom route meta, permissions, and login redirects.</li><li>Run <code>pnpm check</code> and relevant <code>pnpm test:e2e</code> scenarios.</li></ol><h2 id="old-implementations-not-restored" tabindex="-1">Old Implementations Not Restored <a class="header-anchor" href="#old-implementations-not-restored" aria-label="Permalink to &quot;Old Implementations Not Restored&quot;">​</a></h2><p>The old <code>vite-plugin-pages</code> integration was not restored because implicit routing does not pay off at this scale. The imagemin binary chain was replaced by Sharp/SVGO. Icon fonts were replaced by SVG sprites. QRCode/restart plugins were removed due to Vite 8 peer incompatibility; Vite reloads config itself, and device testing can use the LAN URL or a future CLI.</p>',7)])])}const u=o(n,[["render",r]]);export{g as __pageData,u as default};
